const items = $input.all();
const returnItems = [];

// Verificar si hay items
if (!items || items.length === 0) {
  return [];
}

for (const item of items) {
  // Verificar que el item tenga la estructura correcta
  if (!item || !item.json || !item.json.start || !item.json.start.dateTime) {
    continue; // Saltar este item si no tiene la estructura correcta
  }

  let data = item.json;

  const dia = data.start.dateTime.split('T')[0];
  const inicio = data.start.dateTime.split('T')[1].substring(0, 5);
  const final = data.end.dateTime.split('T')[1].substring(0, 5);

  returnItems.push({
    json: {
      dia: dia,
      inicio: inicio, 
      final: final
    }
  });
}

return returnItems;

// ==========================================
// CALCULAR TURNOS DISPONIBLES - ROBUSTO
// ==========================================

function calcularTurnosDisponibles() {

  // Helper: Formato de fecha completo → "Jueves 04/12/2025"
  function formatoFechaCompleta(fechaStr) {
    const dias = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
    const fecha = new Date(fechaStr + "T00:00:00");
    const diaSemana = dias[fecha.getDay()];
    const dd = fecha.getDate().toString().padStart(2,'0');
    const mm = (fecha.getMonth()+1).toString().padStart(2,'0');
    const yyyy = fecha.getFullYear();
    return `${diaSemana} ${dd}/${mm}/${yyyy}`;
  }

  // 1. OBTENER TIEMPO DE SERVICIO
  const tiempoData = $('When Executed by Another Workflow').first().json;
  let TIEMPO_SERVICIO = 30; // fallback

  if (tiempoData?.query) {
    if (typeof tiempoData.query === 'string' && tiempoData.query.includes(':')) {
      const [hours, minutes] = tiempoData.query.split(':').map(Number);
      TIEMPO_SERVICIO = (hours * 60) + minutes;
    } else {
      TIEMPO_SERVICIO = parseInt(tiempoData.query) || 30;
    }
  }

  // 2. TIEMPO LAVADO
  const TIEMPO_LAVADO = 45;

  // 3. TIEMPOS FIJOS
  const TIEMPO_RECEPCION = 15;
  const TIEMPO_PREPARACION = 15;

  // 4. OBTENER DATOS
  const feriadosData = $('feriados').first().json.feriadosEncontrados || [];
  const tallerData = $('Get row(s) in sheet').first().json;
  const turnosOcupadosRaw = $('Code').all();

  // 5. PROCESAR TURNOS OCUPADOS (con soporte Google Calendar)
  const turnosOcupados = [];

  turnosOcupadosRaw.forEach(item => {
    const data = item.json;

    // Caso 1: array directo de turnos preprocesados
    if (Array.isArray(data)) {
      data.forEach(t => {
        if (t?.dia && t?.inicio && t?.final) turnosOcupados.push(t);
      });
      return;
    }

    // Caso 2: evento de Google Calendar (start.dateTime / end.dateTime)
    if (data?.start?.dateTime && data?.end?.dateTime) {
      const dia = data.start.dateTime.split('T')[0];
      const inicio = data.start.dateTime.split('T')[1].slice(0,5);
      const final = data.end.dateTime.split('T')[1].slice(0,5);
      turnosOcupados.push({ dia, inicio, final });
      return;
    }

    // Caso 3: formato simple (ya normalizado)
    if (data?.dia && data?.inicio && data?.final) {
      turnosOcupados.push(data);
    }
  });

  // 6. FUNCIONES AUXILIARES
  function timeToMinutes(timeStr) {
    if (!timeStr) return 0;
    const [h, m] = timeStr.split(':').map(Number);
    return (h * 60) + (m || 0);
  }

  function minutesToTime(min) {
    min = ((min % 1440) + 1440) % 1440; // normaliza al rango del día
    const h = Math.floor(min / 60);
    const m = min % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  }

  function cruza(inicio, fin, ini2, fin2) {
    return (inicio < fin2 && fin > ini2);
  }

  // 7. HORARIOS DEL TALLER
  const apertura = timeToMinutes(tallerData.Apertura);
  const cierre = timeToMinutes(tallerData.Cierre);
  const inicioAlmuerzo = timeToMinutes(tallerData["Inicio Almuerzo"]);
  const finAlmuerzo = timeToMinutes(tallerData["Fin Almuerzo"]);
  const inicioDesayuno = tallerData["Inicio Desayuno"]
    ? timeToMinutes(tallerData["Inicio Desayuno"])
    : null;
  const finDesayuno = tallerData["Fin Desayuno"]
    ? timeToMinutes(tallerData["Fin Desayuno"])
    : null;

  // 8. MARCAR OCUPADOS
  const ocupados = new Set();
  turnosOcupados.forEach(t => {
    if (!t?.dia || !t?.inicio || !t?.final) return;
    const ini = timeToMinutes(t.inicio);
    const fin = timeToMinutes(t.final);
    for (let m = ini; m < fin; m += 15) {
      ocupados.add(`${t.dia}_${minutesToTime(m)}`);
    }
  });

  // 9. BUSCAR TURNOS DISPONIBLES
  const feriados = new Set(feriadosData);
  const turnosDisponibles = [];
  const hoy = new Date();
  let fecha = new Date(hoy);
  fecha.setDate(fecha.getDate() + 2);

  let diasBuscados = 0;

  while (turnosDisponibles.length < 4 && diasBuscados < 60) {
    const fechaStr = fecha.toISOString().split('T')[0];
    const diaSemana = fecha.getDay();

    if (diaSemana >= 1 && diaSemana <= 5 && !feriados.has(fechaStr)) {

      function estaLibre(inicio, duracion) {
        const fin = inicio + duracion;
        if (
          inicioDesayuno !== null &&
          finDesayuno !== null &&
          cruza(inicio, fin, inicioDesayuno, finDesayuno)
        ) return false;

        for (let m = inicio; m < fin; m += 15) {
          if (ocupados.has(`${fechaStr}_${minutesToTime(m)}`)) return false;
        }
        return true;
      }

      for (let hora = apertura; hora + TIEMPO_SERVICIO <= cierre; hora += 15) {
        if (estaLibre(hora, TIEMPO_SERVICIO)) {
          const inicioMin = hora;
          const finServicio = hora + TIEMPO_SERVICIO;
          const tieneAlmuerzo = cruza(inicioMin, finServicio, inicioAlmuerzo, finAlmuerzo);
          const tiempoAlmuerzo = tieneAlmuerzo ? 60 : 0;

          const llegada = inicioMin - TIEMPO_RECEPCION;
          let entrega = finServicio + TIEMPO_LAVADO + TIEMPO_PREPARACION + tiempoAlmuerzo;
          if (entrega > 1440) entrega = entrega % 1440;
          if (entrega >= 780 && entrega < 855) entrega = 900;

          turnosDisponibles.push({
            dia: fechaStr,
            inicio: minutesToTime(inicioMin),
            final: minutesToTime(finServicio),
            horarioLlegada: minutesToTime(llegada),
            horarioEntrega: minutesToTime(entrega),
            fechaFormato: formatoFechaCompleta(fechaStr),
            Id_Calendario: tallerData.Id_Calendario,
            tiempoAlmuerzo
          });

          break;
        }
      }
    }

    fecha.setDate(fecha.getDate() + 1);
    diasBuscados++;
  }

  turnosDisponibles.sort((a, b) =>
    a.dia === b.dia ? a.inicio.localeCompare(b.inicio) : new Date(a.dia) - new Date(b.dia)
  );

  return {
    turnosDisponibles: turnosDisponibles.slice(0, 4),
    tiempoServicio: TIEMPO_SERVICIO,
    tiempoLavado: TIEMPO_LAVADO
  };
}

// === LLAMADA Y RETORNO FINAL ===
const resultado = calcularTurnosDisponibles();

return [{
  json: {
    turnosDisponibles: resultado.turnosDisponibles,
    tiempoServicio: resultado.tiempoServicio,
    tiempoLavado: resultado.tiempoLavado,
    cantidad: resultado.turnosDisponibles.length
  }
}];

function obtenerFeriados() {
  // Obtener los feriados del nodo anterior
  const feriadosData = $input.all(); // Obtiene todos los items del nodo anterior
  const feriados = [];

  // Extraer las fechas de los feriados del formato que recibes
  feriadosData.forEach(item => {
    if (item.json && item.json.start && item.json.start.date) {
      feriados.push(item.json.start.date);
    }
    // Si el feriado dura más de un día, también agregar las fechas intermedias
    if (item.json && item.json.end && item.json.end.date && item.json.start.date !== item.json.end.date) {
      const fechaInicio = new Date(item.json.start.date);
      const fechaFin = new Date(item.json.end.date);

      // Agregar todas las fechas entre inicio y fin
      const fechaActual = new Date(fechaInicio);
      while (fechaActual < fechaFin) {
        feriados.push(fechaActual.toISOString().split('T')[0]);
        fechaActual.setDate(fechaActual.getDate() + 1);
      }
    }
  });

  // Eliminar duplicados de la lista de feriados
  const feriadosUnicos = [...new Set(feriados)];

  return feriadosUnicos;
}

const feriadosEncontrados = obtenerFeriados();

return [{
  json: {
    feriadosEncontrados: feriadosEncontrados
  }
}];

